import { describe, expect, it } from 'vitest'
import { buildSnapshot, isActionable } from '../watch-snapshot'
import {
  bot,
  checkRun,
  issueComment,
  NOW,
  person,
  prState,
  review,
  thread,
  VIEWER,
} from './pr-state-fixtures'

const BABYSIT_REPLY =
  '> _This was generated by AI via the babysit skill._\n\nFixed in abc123.\n\n<!-- babysit -->'

describe('pr:watch snapshot actions', () => {
  it('converges when every check passed and nothing is open', () => {
    const snapshot = buildSnapshot(prState(), NOW)

    expect(snapshot.actions).toEqual([{ type: 'converged' }])
    expect(snapshot.canPush).toBe(true)
  })

  it('stops on a draft, merged or closed PR', () => {
    expect(buildSnapshot(prState({ isDraft: true }), NOW).actions).toEqual([
      { reason: 'draft', type: 'stop' },
    ])
    expect(buildSnapshot(prState({ state: 'MERGED' }), NOW).actions).toEqual([
      { reason: 'merged', type: 'stop' },
    ])
    expect(buildSnapshot(prState({ state: 'CLOSED' }), NOW).actions).toEqual([
      { reason: 'closed', type: 'stop' },
    ])
  })

  it('waits until the head commit reports checks', () => {
    const snapshot = buildSnapshot(prState({ checkRuns: [] }), NOW)

    expect(snapshot.actions).toEqual([
      { reason: 'no checks reported for the head commit yet', type: 'wait' },
    ])
    expect(isActionable(snapshot)).toBe(false)
  })

  it('reports a failing required check and blocks pushes while another runs', () => {
    const snapshot = buildSnapshot(
      prState({
        checkRuns: [
          checkRun({ conclusion: 'FAILURE', id: 101 }),
          checkRun({ conclusion: undefined, id: 102, name: 'Lint', status: 'IN_PROGRESS' }),
        ],
      }),
      NOW,
    )

    expect(snapshot.actions.map((action) => action.type)).toEqual(['diagnose_ci_failure', 'wait'])
    expect(snapshot.canPush).toBe(false)
    expect(snapshot.checks.failed[0]).toMatchObject({
      attempts: 1,
      id: 101,
      logCommand: 'gh run view 7 --job 101 --log-failed',
      retriesLeft: 2,
    })
  })

  it('counts reruns of the same job on the head and keeps only the latest attempt', () => {
    const snapshot = buildSnapshot(
      prState({
        checkRuns: [
          checkRun({ conclusion: 'FAILURE', id: 101 }),
          checkRun({ conclusion: 'FAILURE', id: 103 }),
          checkRun({ conclusion: 'FAILURE', id: 105 }),
        ],
      }),
      NOW,
    )

    expect(snapshot.checks.failed).toHaveLength(1)
    expect(snapshot.checks.failed[0]).toMatchObject({ attempts: 3, id: 105, retriesLeft: 0 })
  })

  it('treats an optional check failure as a warning once some checks are required', () => {
    const snapshot = buildSnapshot(
      prState({
        checkRuns: [
          checkRun(),
          checkRun({ conclusion: 'FAILURE', id: 200, isRequired: false, name: 'Docs' }),
        ],
      }),
      NOW,
    )

    expect(snapshot.actions).toEqual([{ type: 'converged' }])
    expect(snapshot.warnings[0]).toContain('Optional check failed: CI / Docs')
  })

  it('counts every failure as blocking when no check is marked required', () => {
    const snapshot = buildSnapshot(
      prState({ checkRuns: [checkRun({ conclusion: 'FAILURE', isRequired: false })] }),
      NOW,
    )

    expect(snapshot.actions.map((action) => action.type)).toEqual(['diagnose_ci_failure'])
  })

  it('stops for the maintainer when a check waits for approval', () => {
    const snapshot = buildSnapshot(
      prState({ checkRuns: [checkRun({ conclusion: 'ACTION_REQUIRED' })] }),
      NOW,
    )

    expect(snapshot.actions).toEqual([{ reason: 'checks_need_approval', type: 'stop' }])
  })

  it('folds commit statuses in with check runs', () => {
    const snapshot = buildSnapshot(
      prState({
        statusContexts: [
          { context: 'deploy', isRequired: false, state: 'PENDING', url: undefined },
        ],
      }),
      NOW,
    )

    expect(snapshot.checks.running).toEqual(['deploy'])
    expect(snapshot.canPush).toBe(false)
  })

  it('changes the signature when a check finishes', () => {
    const running = buildSnapshot(
      prState({ checkRuns: [checkRun({ status: 'IN_PROGRESS' })] }),
      NOW,
    )
    const done = buildSnapshot(prState(), NOW)

    expect(running.signature).not.toBe(done.signature)
  })
})

describe('pr:watch review comments', () => {
  it('lists an unresolved thread with the comment id to reply to', () => {
    const snapshot = buildSnapshot(prState({ threads: [thread({ isOutdated: true })] }), NOW)

    expect(snapshot.actions).toEqual([{ count: 1, type: 'handle_comments' }])
    expect(snapshot.openItems[0]).toMatchObject({
      kind: 'thread',
      outdated: true,
      path: 'src/main/x.ts',
      reply: { commentId: 900 },
    })
  })

  it('closes a thread whose latest comment is a babysit reply, and reopens it on a later reply', () => {
    const base = thread()
    const [firstComment] = base.comments
    if (!firstComment) throw new Error('Expected the fixture thread to have a comment')
    const babysitReply = {
      ...firstComment,
      author: person(VIEWER),
      body: BABYSIT_REPLY,
      id: 901,
      url: 'u901',
    }
    const answered = buildSnapshot(
      prState({ threads: [{ ...base, comments: [...base.comments, babysitReply] }] }),
      NOW,
    )
    const reopened = buildSnapshot(
      prState({
        threads: [
          {
            ...base,
            comments: [
              ...base.comments,
              babysitReply,
              { ...babysitReply, author: person('reviewer'), body: 'Not quite.', id: 902 },
            ],
          },
        ],
      }),
      NOW,
    )

    expect(answered.openItems).toEqual([])
    expect(answered.answeredThreads).toHaveLength(1)
    expect(reopened.openItems).toHaveLength(1)
  })

  it('ignores resolved threads', () => {
    expect(
      buildSnapshot(prState({ threads: [thread({ isResolved: true })] }), NOW).openItems,
    ).toEqual([])
  })

  it('closes a conversation comment once a babysit reply names it', () => {
    const comment = issueComment({ id: 41 })
    const open = buildSnapshot(prState({ comments: [comment] }), NOW)
    const reply = issueComment({
      author: person(VIEWER),
      body: `${BABYSIT_REPLY}\n<!-- babysit:reply-to:comment-41 -->`,
      id: 42,
    })
    const closed = buildSnapshot(prState({ comments: [comment, reply] }), NOW)

    expect(open.openItems[0]?.reply).toEqual({ marker: '<!-- babysit:reply-to:comment-41 -->' })
    expect(closed.openItems).toEqual([])
  })

  it('skips managed reports and deploy previews but keeps other bot comments', () => {
    const snapshot = buildSnapshot(
      prState({
        comments: [
          issueComment({
            author: person(VIEWER),
            body: 'report\n<!-- openwaggle:blast-radius-report -->',
            id: 10,
          }),
          issueComment({
            author: bot('cloudflare-workers-and-pages'),
            body: 'Deploying openwaggle',
            id: 11,
          }),
          issueComment({ author: bot('some-linter'), body: 'Found 2 issues', id: 12 }),
        ],
      }),
      NOW,
    )

    expect(snapshot.openItems.map((item) => item.author)).toEqual(['some-linter'])
  })

  it('lists a review body from a person until a babysit reply names it', () => {
    const changes = review({ body: 'Split this PR.', id: 60, state: 'CHANGES_REQUESTED' })
    const open = buildSnapshot(prState({ reviews: [changes] }), NOW)
    const reply = issueComment({
      author: person(VIEWER),
      body: `${BABYSIT_REPLY}\n<!-- babysit:reply-to:review-60 -->`,
      id: 61,
    })

    expect(open.openItems[0]).toMatchObject({
      kind: 'review',
      reply: { marker: '<!-- babysit:reply-to:review-60 -->' },
    })
    expect(
      buildSnapshot(prState({ comments: [reply], reviews: [changes] }), NOW).openItems,
    ).toEqual([])
  })
})
